import React, { useContext, useEffect, useMemo, useState } from 'react';
import logo from '../assets/logo.png';
import { AuthContext } from '../components/AuthContext';

const API_BASE = process.env.REACT_APP_API_BASE || ''; // '' if CRA proxy is set to /api

function genCode() { return 'P' + Math.floor(100000 + Math.random() * 900000); }
function genBarcode() { return String(Math.floor(100000000000 + Math.random() * 900000000000)); }

function tryParseError(text, fallback) {
  try { const j = JSON.parse(text); return j?.error || j?.message || fallback || 'Request failed'; }
  catch { return text || fallback || 'Request failed'; }
}

const emptyForm = {
  productId: null,
  categoryId: '',
  supplierId: '',
  name: '',
  genericName: '',
  stock: '',
  price: '',
  costPrice: '',
  expiryDate: '',
  productCode: '',
  barcode: '',
  minStock: '',
  maxStock: '',
  maxDiscount: '',
  patientInstructions: '',
  binLocation: '',
  image: '' // not sent to backend (placeholder for your future upload)
};

const pageSize = 10;

const ProductManagement = () => {
  const { token: ctxToken, roles = [] } = useContext(AuthContext);
  const token = useMemo(() => ctxToken || localStorage.getItem('token') || '', [ctxToken]);
  const isAdmin = (roles?.map?.(r => r.toLowerCase()) || JSON.parse(localStorage.getItem('roles') || '[]')
    .map(r => r.toLowerCase())).includes('admin');

  const authHeaders = token ? { Authorization: `Bearer ${token}` } : {};

  const [categories, setCategories] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [list, setList] = useState([]);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // search + paging (client-side for now)
  const [search, setSearch] = useState({ category: '', code: '', name: '', generic: '' });
  const [page, setPage] = useState(1);

  // Load reference data + products
  useEffect(() => {
    const loadRefs = async () => {
      setError('');
      try {
        const [catRes, supRes] = await Promise.all([
          fetch(`${API_BASE}/api/categories`, { headers: { ...authHeaders } }),
          fetch(`${API_BASE}/api/suppliers`, { headers: { ...authHeaders } })
        ]);
        const [catData, supData] = await Promise.all([catRes.json(), supRes.json()]);
        if (!catRes.ok) throw new Error(catData?.message || 'Failed to load categories');
        if (!supRes.ok) throw new Error(supData?.message || 'Failed to load suppliers');
        setCategories(catData);
        setSuppliers(supData);
      } catch (e) {
        setError(e.message);
      }
    };
    const loadProducts = async () => {
      setLoading(true);
      setError('');
      try {
        const res = await fetch(`${API_BASE}/api/products`, { headers: { ...authHeaders } });
        const data = await res.json();
        if (!res.ok) throw new Error(data?.message || 'Failed to load products');
        setList(Array.isArray(data) ? data : []);
      } catch (e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    };
    loadRefs();
    loadProducts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleChange = (e) => {
    const { name, value, files, type } = e.target;
    if (files && files[0]) {
      setForm(f => ({ ...f, [name]: URL.createObjectURL(files[0]) })); // preview only
    } else {
      setForm(f => ({ ...f, [name]: type === 'number' ? Number(value) : value }));
    }
  };

  const autoCode = () => setForm(f => ({ ...f, productCode: genCode() }));
  const autoBarcode = () => setForm(f => ({ ...f, barcode: genBarcode() }));

  const reset = () => setForm(emptyForm);

  const createOrUpdate = async (payload, id) => {
    const url = id ? `${API_BASE}/api/products/${id}` : `${API_BASE}/api/products`;
    const method = id ? 'PUT' : 'POST';
    const res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json', ...authHeaders },
      body: JSON.stringify(payload)
    });
    const text = await res.text();
    if (!res.ok) throw new Error(tryParseError(text, res.statusText));
    return JSON.parse(text);
  };

  const loadProducts = async () => {
    const res = await fetch(`${API_BASE}/api/products`, { headers: { ...authHeaders } });
    const data = await res.json();
    if (!res.ok) throw new Error(data?.message || 'Failed to load products');
    setList(Array.isArray(data) ? data : []);
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setError('');
    // minimal required fields
    if (!form.name || !form.price || !form.costPrice) {
      setError('Name, Cost Price and Sell Price are required');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name?.trim(),
        genericName: form.genericName?.trim() || null,
        categoryId: form.categoryId ? Number(form.categoryId) : null,
        supplierId: form.supplierId ? Number(form.supplierId) : null,
        productCode: form.productCode?.trim() || null,
        barcode: form.barcode?.trim() || null,
        costPrice: Number(form.costPrice),
        price: Number(form.price),
        stock: form.stock === '' ? 0 : Number(form.stock),
        minStock: form.minStock === '' ? null : Number(form.minStock),
        maxStock: form.maxStock === '' ? null : Number(form.maxStock),
        maxDiscount: form.maxDiscount === '' ? null : Number(form.maxDiscount),
        expiryDate: form.expiryDate || null, // yyyy-mm-dd
        patientInstructions: form.patientInstructions || null,
        binLocation: form.binLocation || null
      };

      await createOrUpdate(payload, form.productId);
      await loadProducts();
      reset();
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };

  const onEdit = (p) => {
    setForm({
      productId: p.productId,
      categoryId: p.categoryId || '',
      supplierId: p.supplierId || '',
      name: p.name || '',
      genericName: p.genericName || '',
      stock: p.stock ?? '',
      price: p.price ?? '',
      costPrice: p.costPrice ?? '',
      expiryDate: p.expiryDate || '',
      productCode: p.productCode || '',
      barcode: p.barcode || '',
      minStock: p.minStock ?? '',
      maxStock: p.maxStock ?? '',
      maxDiscount: p.maxDiscount ?? '',
      patientInstructions: p.patientInstructions || '',
      binLocation: p.binLocation || '',
      image: ''
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const onDelete = async (id) => {
    if (!window.confirm(`Delete product #${id}?`)) return;
    setError('');
    try {
      const res = await fetch(`${API_BASE}/api/products/${id}`, {
        method: 'DELETE',
        headers: { ...authHeaders }
      });
      const text = await res.text();
      if (!res.ok) throw new Error(tryParseError(text, res.statusText));
      setList(prev => prev.filter(x => x.productId !== id));
      if (form.productId === id) reset();
    } catch (e) {
      setError(e.message);
    }
  };

  // Client-side filtering
  const filtered = list.filter(p =>
    (!search.category || (p.categoryName || '').toLowerCase().includes(search.category.toLowerCase())) &&
    (!search.code || (p.productCode || '').toLowerCase().includes(search.code.toLowerCase())) &&
    (!search.name || (p.name || '').toLowerCase().includes(search.name.toLowerCase())) &&
    (!search.generic || (p.genericName || '').toLowerCase().includes(search.generic.toLowerCase()))
  );
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const pageSafe = Math.min(page, totalPages);
  const paginated = filtered.slice((pageSafe - 1) * pageSize, pageSafe * pageSize);

  return (
    <div style={{ padding: 24 }}>
      <h2>Product Management</h2>

      {/* Add / Edit Product */}
      <form onSubmit={onSubmit}
        style={{ display: 'flex', flexWrap: 'wrap', gap: 24, marginBottom: 24, background: '#f5f5f5', padding: 20, borderRadius: 8 }}>
        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 180 }}>
          <label>Category</label>
          <select name="categoryId" value={form.categoryId} onChange={handleChange} style={{ padding: 8 }}>
            <option value="">Select Category</option>
            {categories.map(c => <option key={c.categoryId} value={c.categoryId}>{c.name}</option>)}
          </select>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 220 }}>
          <label>Product Name</label>
          <input name="name" value={form.name} onChange={handleChange} required style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 220 }}>
          <label>Generic Name</label>
          <input name="genericName" value={form.genericName} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 180 }}>
          <label>Supplier</label>
          <select name="supplierId" value={form.supplierId} onChange={handleChange} style={{ padding: 8 }}>
            <option value="">Select Supplier</option>
            {suppliers.map(s => <option key={s.supplierId} value={s.supplierId}>{s.name}</option>)}
          </select>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 120 }}>
          <label>Stock</label>
          <input type="number" name="stock" value={form.stock} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 140 }}>
          <label>Cost Price</label>
          <input type="number" step="0.01" name="costPrice" value={form.costPrice} onChange={handleChange} required style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 140 }}>
          <label>Sell Price</label>
          <input type="number" step="0.01" name="price" value={form.price} onChange={handleChange} required style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 170 }}>
          <label>Expiry Date</label>
          <input type="date" name="expiryDate" value={form.expiryDate} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 200 }}>
          <label>Product Code</label>
          <div style={{ display: 'flex', gap: 8 }}>
            <input name="productCode" value={form.productCode} onChange={handleChange} placeholder="Auto-generate if empty" style={{ padding: 8, flex: 1 }} />
            <button type="button" onClick={autoCode}>Auto</button>
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 200 }}>
          <label>Barcode</label>
          <div style={{ display: 'flex', gap: 8 }}>
            <input name="barcode" value={form.barcode} onChange={handleChange} placeholder="Auto-generate if empty" style={{ padding: 8, flex: 1 }} />
            <button type="button" onClick={autoBarcode}>Auto</button>
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 120 }}>
          <label>Min Stock</label>
          <input type="number" name="minStock" value={form.minStock} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 120 }}>
          <label>Max Stock</label>
          <input type="number" name="maxStock" value={form.maxStock} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 150 }}>
          <label>Max Discount %</label>
          <input type="number" step="0.01" name="maxDiscount" value={form.maxDiscount} onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 260 }}>
          <label>Patient Instructions</label>
          <input name="patientInstructions" value={form.patientInstructions} onChange={handleChange} placeholder="e.g., after meals" style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 160 }}>
          <label>Bin Location</label>
          <input name="binLocation" value={form.binLocation} onChange={handleChange} placeholder="A1-03" style={{ padding: 8 }} />
        </div>

        {/* Placeholder for image preview / future upload */}
        <div style={{ display: 'flex', flexDirection: 'column', minWidth: 180 }}>
          <label>Product Image</label>
          <input name="image" type="file" accept="image/*" onChange={handleChange} style={{ padding: 8 }} />
        </div>

        <div style={{ display: 'flex', alignItems: 'end', gap: 8 }}>
          <button type="submit" disabled={saving || !isAdmin}
            title={!isAdmin ? 'Only admins can create/update' : undefined}
            style={{ marginTop: 24, padding: '7px 18px', fontSize: 15, background: '#43ea7a', color: '#000', border: '1px solid #0c0', borderRadius: 4 }}>
            {form.productId ? (saving ? 'Updating…' : 'Update Product') : (saving ? 'Adding…' : 'Add Product')}
          </button>
          {form.productId && (
            <button type="button" onClick={reset} disabled={saving}
              style={{ marginTop: 24, padding: '7px 18px', fontSize: 15, background: '#eee', border: '1px solid #ccc', borderRadius: 4 }}>
              Cancel
            </button>
          )}
        </div>
      </form>

      {error && <div style={{ color: 'red', marginBottom: 12 }}>{error}</div>}
      {loading && <div>Loading…</div>}

      {/* Search */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 16 }}>
        <input placeholder="Search by Category" value={search.category} onChange={e => setSearch(s => ({ ...s, category: e.target.value }))} style={{ padding: 8, minWidth: 160 }} />
        <input placeholder="Search by Product Code" value={search.code} onChange={e => setSearch(s => ({ ...s, code: e.target.value }))} style={{ padding: 8, minWidth: 160 }} />
        <input placeholder="Search by Name" value={search.name} onChange={e => setSearch(s => ({ ...s, name: e.target.value }))} style={{ padding: 8, minWidth: 160 }} />
        <input placeholder="Search by Generic Name" value={search.generic} onChange={e => setSearch(s => ({ ...s, generic: e.target.value }))} style={{ padding: 8, minWidth: 180 }} />
      </div>

      {/* List */}
      <table style={{ width: '100%', borderCollapse: 'collapse', background: '#fafafa' }}>
        <thead>
          <tr style={{ background: '#f0f0f0' }}>
            <th>Image</th>
            <th>Product Name</th>
            <th>Generic Name</th>
            <th>Category</th>
            <th>Supplier</th>
            <th>Stock</th>
            <th>Cost</th>
            <th>Sell</th>
            <th>Expiry</th>
            <th>Product Code</th>
            <th>Barcode</th>
            <th>Min</th>
            <th>Max</th>
            <th>Max Disc %</th>
            <th>Bin</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {paginated.map(p => (
            <tr key={p.productId}>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>
                <img src={logo} alt="Product" style={{ width: 40, height: 40, objectFit: 'cover', borderRadius: 4 }} />
              </td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.name}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.genericName || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.categoryName || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.supplierName || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.stock ?? 0}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.costPrice?.toFixed ? p.costPrice.toFixed(2) : p.costPrice}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.price?.toFixed ? p.price.toFixed(2) : p.price}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.expiryDate || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.productCode || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.barcode || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.minStock ?? '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.maxStock ?? '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.maxDiscount ?? '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>{p.binLocation || '-'}</td>
              <td style={{ padding: 6, border: '1px solid #ddd' }}>
                <button onClick={() => onEdit(p)} style={{ background: '#ffe066', color: '#333', border: 'none', borderRadius: 4, padding: '6px 12px' }}>Edit</button>
                <button onClick={() => onDelete(p.productId)} disabled={!isAdmin}
                  title={!isAdmin ? 'Only admins can delete' : undefined}
                  style={{ marginLeft: 8, background: '#ff6b6b', color: '#fff', border: 'none', borderRadius: 4, padding: '6px 12px' }}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
          {paginated.length === 0 && (
            <tr><td colSpan={16} style={{ padding: 10, textAlign: 'center' }}>No products</td></tr>
          )}
        </tbody>
      </table>

      {/* Pagination */}
      <div style={{ marginTop: 16, display: 'flex', justifyContent: 'center', gap: 8 }}>
        <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={pageSafe === 1}>Prev</button>
        <span>Page {pageSafe} of {totalPages}</span>
        <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={pageSafe === totalPages}>Next</button>
      </div>
    </div>
  );
};

export default ProductManagement;
